// ==================== VIOLET BEAUTY - COMPLETE E-COMMERCE SCRIPT ====================

// ===== GLOBAL STATE =====
let cart = JSON.parse(localStorage.getItem('vb_cart') || '[]');
let favorites = JSON.parse(localStorage.getItem('vb_favorites') || '[]');
let subscribers = JSON.parse(localStorage.getItem('vb_subscribers') || '[]');
let users = JSON.parse(localStorage.getItem('vb_users') || '[]');
let currentUser = JSON.parse(localStorage.getItem('vb_current_user') || 'null');

// ===== SAVE STATE =====
function saveCart() { localStorage.setItem('vb_cart', JSON.stringify(cart)); }
function saveFavorites() { localStorage.setItem('vb_favorites', JSON.stringify(favorites)); }
function saveUsers() { localStorage.setItem('vb_users', JSON.stringify(users)); }
function saveCurrentUser() { localStorage.setItem('vb_current_user', JSON.stringify(currentUser)); }

// ===== NAVBAR SCROLL =====
const navbar = document.getElementById('navbar');
if (navbar) {
  window.addEventListener('scroll', () => {
    navbar.classList.toggle('scrolled', window.scrollY > 50);
  });
}

// ===== RIPPLE EFFECT =====
function rippleEffect(e) {
  const btn = e.currentTarget;
  const ripple = document.createElement('div');
  ripple.className = 'ripple';
  const rect = btn.getBoundingClientRect();
  const size = Math.max(rect.width, rect.height);
  ripple.style.cssText = `width:${size}px;height:${size}px;left:${e.clientX-rect.left-size/2}px;top:${e.clientY-rect.top-size/2}px;`;
  btn.appendChild(ripple);
  setTimeout(() => ripple.remove(), 700);
}

// ===== SCROLL REVEAL =====
const reveals = document.querySelectorAll('.reveal');
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => { if (entry.isIntersecting) entry.target.classList.add('visible'); });
}, { threshold: 0.12 });
reveals.forEach(el => observer.observe(el));

// ===== PARTICLES =====
function createParticles() {
  const colors = ['#a78bfa','#f9a8d4','#d4af7a'];
  for (let i = 0; i < 12; i++) {
    const p = document.createElement('div');
    p.className = 'particle';
    p.style.cssText = `left:${Math.random()*100}%;top:${Math.random()*100}%;background:${colors[Math.floor(Math.random()*colors.length)]};width:${4+Math.random()*6}px;height:${4+Math.random()*6}px;animation-delay:${Math.random()*6}s;animation-duration:${5+Math.random()*4}s;position:fixed;pointer-events:none;z-index:0;border-radius:50%;opacity:0;animation-name:particle-float;animation-iteration-count:infinite;`;
    document.body.appendChild(p);
  }
}
createParticles();

// ===== CART FUNCTIONS =====
function getCartTotal() {
  return cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function updateCartBadges() {
  const totalQty = cart.reduce((sum, item) => sum + item.qty, 0);
  document.querySelectorAll('#cart-count, .cart-badge').forEach(el => { el.textContent = totalQty; });
  const cartBadge = document.querySelector('.nav-cart-badge');
  if (cartBadge) { cartBadge.textContent = totalQty; cartBadge.style.display = totalQty > 0 ? 'flex' : 'none'; }
}

function updateFavBadges() {
  document.querySelectorAll('.fav-badge').forEach(el => { el.textContent = favorites.length; });
}

function renderCartItems() {
  const cartItemsEl = document.getElementById('cart-items');
  const cartTotalEl = document.getElementById('cart-total-price');
  const sidebarCount = document.getElementById('sidebar-cart-count');
  if (!cartItemsEl) return;

  if (cart.length === 0) {
    cartItemsEl.innerHTML = `<div style="text-align:center;padding:60px 20px;color:#9ca3af;">
      <div style="font-size:48px;margin-bottom:16px;color:#a78bfa;"><i class="fa-solid fa-bag-shopping"></i></div>
      <p style="font-size:16px;font-weight:500;">Your cart is empty</p>
      <p style="font-size:13px;margin-top:8px;">Add some beautiful products!</p>
    </div>`;
  } else {
    cartItemsEl.innerHTML = cart.map((item, i) => {
      const imgSrc = item.img || getProductImg(item.name);
      const icon = imgSrc
        ? `<img src="${imgSrc}" alt="${item.name}" style="width:100%;height:100%;object-fit:cover;border-radius:14px;" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><i class="fa-solid ${item.emoji && item.emoji.startsWith('fa-') ? item.emoji : 'fa-pump-soap'}" style="display:none;font-size:22px;color:#7c3aed;"></i>`
        : `<i class="fa-solid ${item.emoji && item.emoji.startsWith('fa-') ? item.emoji : 'fa-pump-soap'}"></i>`;
      return `
      <div class="cart-item">
        <div class="cart-item-icon">${icon}</div>
        <div style="flex:1;min-width:0;">
          <div class="cart-item-name">${item.name}</div>
          <div class="cart-item-price">$${item.price.toFixed(2)} × ${item.qty} = <strong style="color:#7c3aed;">$${(item.price*item.qty).toFixed(2)}</strong></div>
        </div>
        <div style="display:flex;align-items:center;gap:8px;flex-shrink:0;">
          <div style="display:flex;align-items:center;gap:4px;">
            <button onclick="changeQty(${i}, -1)" style="width:28px;height:28px;border:1.5px solid #e9e4f8;background:white;border-radius:50%;cursor:pointer;font-size:15px;display:flex;align-items:center;justify-content:center;color:#7c3aed;font-weight:700;transition:all 0.2s;" onmouseover="this.style.background='#7c3aed';this.style.color='white'" onmouseout="this.style.background='white';this.style.color='#7c3aed'">−</button>
            <span style="font-weight:700;min-width:22px;text-align:center;color:#18181b;">${item.qty}</span>
            <button onclick="changeQty(${i}, 1)" style="width:28px;height:28px;border:1.5px solid #e9e4f8;background:white;border-radius:50%;cursor:pointer;font-size:15px;display:flex;align-items:center;justify-content:center;color:#7c3aed;font-weight:700;transition:all 0.2s;" onmouseover="this.style.background='#7c3aed';this.style.color='white'" onmouseout="this.style.background='white';this.style.color='#7c3aed'">+</button>
          </div>
          <button class="remove-item" onclick="removeFromCart(${i})">✕</button>
        </div>
      </div>`;
    }).join('');
  }
  if (cartTotalEl) cartTotalEl.textContent = `$${getCartTotal().toFixed(2)}`;
  if (sidebarCount) sidebarCount.textContent = cart.reduce((s, i) => s + i.qty, 0);
}

function addToCart(name, price, emoji = 'fa-pump-soap', img = '') {
  const idx = cart.findIndex(i => i.name === name);
  const resolvedImg = img || getProductImg(name);
  if (idx > -1) { cart[idx].qty++; }
  else { cart.push({ name, price: parseFloat(price), qty: 1, emoji, img: resolvedImg }); }
  saveCart();
  updateCartBadges();
  renderCartItems();
  showToast(`${name} added to cart! 🛍️`);
  openCart();
}

function changeQty(i, delta) {
  cart[i].qty += delta;
  if (cart[i].qty <= 0) cart.splice(i, 1);
  saveCart();
  updateCartBadges();
  renderCartItems();
}

function removeFromCart(i) {
  const name = cart[i].name;
  cart.splice(i, 1);
  saveCart();
  updateCartBadges();
  renderCartItems();
  showToast(`${name} removed`);
}

function clearCart() {
  cart = [];
  saveCart();
  updateCartBadges();
  renderCartItems();
}

function openCart() {
  const sidebar = document.getElementById('cart-sidebar');
  const overlay = document.getElementById('cart-overlay');
  if (sidebar) sidebar.classList.add('open');
  if (overlay) overlay.classList.add('show');
  renderCartItems();
}

function closeCart() {
  const sidebar = document.getElementById('cart-sidebar');
  const overlay = document.getElementById('cart-overlay');
  if (sidebar) sidebar.classList.remove('open');
  if (overlay) overlay.classList.remove('show');
}

// Cart button
const cartBtn = document.getElementById('cart-btn');
if (cartBtn) cartBtn.addEventListener('click', openCart);
const closeCartBtn = document.getElementById('close-cart');
if (closeCartBtn) closeCartBtn.addEventListener('click', closeCart);
const cartOverlay = document.getElementById('cart-overlay');
if (cartOverlay) cartOverlay.addEventListener('click', closeCart);

// ===== FAVORITES FUNCTIONS =====
function toggleFavorite(name, price, emoji = 'fa-pump-soap', img = '') {
  const idx = favorites.findIndex(f => f.name === name);
  const resolvedImg = img || getProductImg(name);
  if (idx > -1) {
    favorites.splice(idx, 1);
    showToast(`${name} removed from favorites`);
  } else {
    favorites.push({ name, price: parseFloat(price), emoji, img: resolvedImg });
    showToast(`${name} added to favorites! ❤️`);
  }
  saveFavorites();
  updateFavBadges();
  updateWishlistButtons();
}

function isFavorite(name) {
  return favorites.some(f => f.name === name);
}

function updateWishlistButtons() {
  document.querySelectorAll('.wishlist-btn').forEach(btn => {
    const name = btn.dataset.name;
    if (name) {
      btn.textContent = isFavorite(name) ? '💜' : '🤍';
    }
  });
}

// ===== ADD TO CART & WISHLIST — event delegation (works with dynamic cards) =====
document.addEventListener('click', function(e) {
  const cartBtn = e.target.closest('.add-cart-btn');
  if (cartBtn) {
    e.stopPropagation();
    const name  = cartBtn.dataset.name;
    const price = cartBtn.dataset.price;
    const icon  = cartBtn.dataset.faicon || 'fa-pump-soap';
    if (name && price) {
      addToCart(name, price, icon);
      cartBtn.textContent = '✓ Added!';
      cartBtn.style.background = 'linear-gradient(135deg,#059669,#10b981)';
      setTimeout(() => { cartBtn.textContent = 'Add to Cart'; cartBtn.style.background = ''; }, 1500);
    }
    return;
  }
  const favBtn = e.target.closest('.wishlist-btn');
  if (favBtn) {
    e.stopPropagation();
    const name  = favBtn.dataset.name;
    const price = favBtn.dataset.price;
    const icon  = favBtn.dataset.faicon || 'fa-pump-soap';
    if (name) {
      toggleFavorite(name, price, icon);
      favBtn.textContent = isFavorite(name) ? '💜' : '🤍';
      favBtn.style.transform = 'scale(1.4)';
      setTimeout(() => { favBtn.style.transform = ''; }, 300);
    }
  }
});

// ===== TOAST NOTIFICATIONS =====
function showToast(msg, type = 'success') {
  let container = document.getElementById('toast-container');
  if (!container) {
    container = document.createElement('div');
    container.id = 'toast-container';
    container.style.cssText = 'position:fixed;bottom:30px;right:30px;z-index:9999;display:flex;flex-direction:column;gap:10px;';
    document.body.appendChild(container);
  }
  const toast = document.createElement('div');
  toast.style.cssText = `background:${type==='error'?'#ef4444':'#18181b'};color:white;padding:14px 20px;border-radius:14px;font-size:14px;font-weight:500;box-shadow:0 10px 30px rgba(0,0,0,0.2);transform:translateX(120%);transition:transform 0.4s cubic-bezier(0.34,1.56,0.64,1);display:flex;align-items:center;gap:8px;max-width:320px;`;
  toast.textContent = msg;
  container.appendChild(toast);
  setTimeout(() => { toast.style.transform = 'translateX(0)'; }, 10);
  setTimeout(() => { toast.style.transform = 'translateX(120%)'; setTimeout(() => toast.remove(), 400); }, 3000);
}

// ===== LOGIN MODAL =====
function openLoginModal() {
  let modal = document.getElementById('login-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'login-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9000;display:flex;align-items:center;justify-content:center;padding:20px;';
    modal.innerHTML = `
      <div style="position:absolute;inset:0;background:rgba(0,0,0,0.5);backdrop-filter:blur(8px);" onclick="closeLoginModal()"></div>
      <div style="background:white;border-radius:28px;padding:48px;width:100%;max-width:420px;position:relative;z-index:1;box-shadow:0 30px 80px rgba(0,0,0,0.2);animation:modal-in 0.4s cubic-bezier(0.34,1.56,0.64,1);">
        <button onclick="closeLoginModal()" style="position:absolute;top:16px;right:16px;background:none;border:none;font-size:20px;cursor:pointer;color:#9ca3af;">✕</button>
        <div style="text-align:center;margin-bottom:32px;">
          <div style="font-size:40px;margin-bottom:8px;color:#7c3aed;"><i class="fa-solid fa-spa"></i></div>
          <h2 style="font-family:'Cormorant Garamond',serif;font-size:28px;font-weight:600;color:#18181b;" id="modal-title">Welcome Back</h2>
          <p style="font-size:14px;color:#9ca3af;margin-top:6px;" id="modal-subtitle">Sign in to your Violet Beauty account</p>
        </div>
        <div id="modal-form">
          <div id="form-name-field" style="display:none;margin-bottom:16px;">
            <input type="text" id="modal-name" placeholder="Full Name" style="width:100%;padding:14px 18px;border:2px solid #e5e7eb;border-radius:14px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;transition:border-color 0.2s;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
          </div>
          <div style="margin-bottom:16px;">
            <input type="email" id="modal-email" placeholder="Email Address" style="width:100%;padding:14px 18px;border:2px solid #e5e7eb;border-radius:14px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;transition:border-color 0.2s;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
          </div>
          <div style="margin-bottom:24px;">
            <input type="password" id="modal-password" placeholder="Password" style="width:100%;padding:14px 18px;border:2px solid #e5e7eb;border-radius:14px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;transition:border-color 0.2s;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
          </div>
          <button onclick="handleAuth()" style="width:100%;padding:16px;background:linear-gradient(135deg,#7c3aed,#a78bfa);color:white;border:none;border-radius:50px;font-size:15px;font-weight:600;cursor:pointer;font-family:'DM Sans',sans-serif;transition:all 0.3s;box-shadow:0 8px 20px rgba(124,58,237,0.3);" onmouseover="this.style.transform='translateY(-2px)'" onmouseout="this.style.transform=''">Sign In</button>
          <p style="text-align:center;margin-top:20px;font-size:13.5px;color:#6b7280;" id="modal-switch-text">Don't have an account? <a href="#" onclick="toggleAuthMode()" style="color:#7c3aed;font-weight:600;text-decoration:none;">Sign Up</a></p>
        </div>
      </div>`;
    document.body.appendChild(modal);
  }
  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
}

let isSignUp = false;
function toggleAuthMode() {
  isSignUp = !isSignUp;
  document.getElementById('modal-title').textContent = isSignUp ? 'Create Account' : 'Welcome Back';
  document.getElementById('modal-subtitle').textContent = isSignUp ? 'Join the Violet Beauty family' : 'Sign in to your Violet Beauty account';
  document.getElementById('form-name-field').style.display = isSignUp ? 'block' : 'none';
  document.getElementById('modal-switch-text').innerHTML = isSignUp
    ? 'Already have an account? <a href="#" onclick="toggleAuthMode()" style="color:#7c3aed;font-weight:600;text-decoration:none;">Sign In</a>'
    : 'Don\'t have an account? <a href="#" onclick="toggleAuthMode()" style="color:#7c3aed;font-weight:600;text-decoration:none;">Sign Up</a>';
  document.querySelector('#modal-form button').textContent = isSignUp ? 'Create Account' : 'Sign In';
}

function handleAuth() {
  const email = document.getElementById('modal-email').value.trim();
  const password = document.getElementById('modal-password').value;
  const name = isSignUp ? document.getElementById('modal-name')?.value.trim() : '';
  if (!email || !password) { showToast('Please fill in all fields', 'error'); return; }
  if (isSignUp) {
    if (users.find(u => u.email === email)) { showToast('Email already exists', 'error'); return; }
    const user = { name: name || email.split('@')[0], email, password };
    users.push(user);
    saveUsers();
    currentUser = user;
    saveCurrentUser();
    showToast(`Welcome, ${user.name}! 🌸`);
  } else {
    const user = users.find(u => u.email === email && u.password === password);
    if (!user) { showToast('Invalid email or password', 'error'); return; }
    currentUser = user;
    saveCurrentUser();
    showToast(`Welcome back, ${user.name}! 💜`);
  }
  closeLoginModal();
  updateLoginButtons();
}

function closeLoginModal() {
  const modal = document.getElementById('login-modal');
  if (modal) modal.style.display = 'none';
  document.body.style.overflow = '';
  isSignUp = false;
}

function logout() {
  currentUser = null;
  saveCurrentUser();
  showToast('Logged out successfully');
  updateLoginButtons();
}

function updateLoginButtons() {
  document.querySelectorAll('.login-btn').forEach(btn => {
    if (currentUser) {
      btn.textContent = currentUser.name.split(' ')[0];
      btn.onclick = () => {
        if (confirm(`Logged in as ${currentUser.name}\n\nClick OK to log out.`)) logout();
      };
    } else {
      btn.textContent = 'Login';
      btn.onclick = openLoginModal;
    }
  });
}

document.querySelectorAll('.login-btn').forEach(btn => { btn.addEventListener('click', openLoginModal); });

// ===== NEWSLETTER SUBSCRIBE =====
function handleSubscribe(inputEl) {
  const email = inputEl?.value?.trim() || document.querySelector('.newsletter-input')?.value?.trim();
  if (!email || !email.includes('@')) { showToast('Please enter a valid email address', 'error'); return; }
  if (subscribers.includes(email)) { showToast('You\'re already subscribed! 🌸'); return; }
  subscribers.push(email);
  localStorage.setItem('vb_subscribers', JSON.stringify(subscribers));
  showToast('Welcome to the Beauty Club! 🌸 Check your email for 15% off.');
  if (inputEl) inputEl.value = '';
  else { const input = document.querySelector('.newsletter-input'); if (input) input.value = ''; }
}

document.querySelectorAll('.subscribe-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const input = btn.closest('.newsletter-form')?.querySelector('input');
    handleSubscribe(input);
  });
});

// ===== CHECKOUT =====
function handleCheckout() {
  if (cart.length === 0) { showToast('Your cart is empty!', 'error'); return; }
  if (!currentUser) { closeCart(); openLoginModal(); showToast('Please sign in to checkout', 'error'); return; }
  openCheckoutModal();
}

function openCheckoutModal() {
  let modal = document.getElementById('checkout-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'checkout-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9000;display:flex;align-items:center;justify-content:center;padding:20px;overflow-y:auto;';
    document.body.appendChild(modal);
  }
  const total = getCartTotal();
  modal.innerHTML = `
    <div style="position:absolute;inset:0;background:rgba(0,0,0,0.5);backdrop-filter:blur(8px);" onclick="closeCheckoutModal()"></div>
    <div style="background:white;border-radius:28px;padding:40px;width:100%;max-width:520px;position:relative;z-index:1;box-shadow:0 30px 80px rgba(0,0,0,0.2);animation:modal-in 0.4s cubic-bezier(0.34,1.56,0.64,1);margin:auto;">
      <button onclick="closeCheckoutModal()" style="position:absolute;top:16px;right:16px;background:none;border:none;font-size:20px;cursor:pointer;color:#9ca3af;">✕</button>
      <h2 style="font-family:'Cormorant Garamond',serif;font-size:26px;font-weight:600;margin-bottom:6px;">Checkout</h2>
      <p style="font-size:14px;color:#9ca3af;margin-bottom:28px;">Complete your order</p>
      <div style="background:#f9f9f9;border-radius:16px;padding:20px;margin-bottom:24px;">
        <p style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:14px;">Order Summary</p>
        ${cart.map(i => `<div style="display:flex;justify-content:space-between;margin-bottom:10px;font-size:14px;"><span>${i.name} ×${i.qty}</span><span style="font-weight:600;">$${(i.price*i.qty).toFixed(2)}</span></div>`).join('')}
        <div style="border-top:1px solid #e5e7eb;margin-top:12px;padding-top:12px;display:flex;justify-content:space-between;font-weight:700;font-size:16px;"><span>Total</span><span style="color:#7c3aed;">$${total.toFixed(2)}</span></div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;">
        <input placeholder="First Name" style="padding:13px 16px;border:2px solid #e5e7eb;border-radius:12px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
        <input placeholder="Last Name" style="padding:13px 16px;border:2px solid #e5e7eb;border-radius:12px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
      </div>
      <input placeholder="Address" style="width:100%;padding:13px 16px;border:2px solid #e5e7eb;border-radius:12px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;margin-bottom:14px;box-sizing:border-box;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
      <p style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:14px;">Payment</p>
      <input placeholder="Card Number (demo: 4242 4242 4242 4242)" style="width:100%;padding:13px 16px;border:2px solid #e5e7eb;border-radius:12px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;margin-bottom:14px;box-sizing:border-box;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:24px;">
        <input placeholder="MM/YY" style="padding:13px 16px;border:2px solid #e5e7eb;border-radius:12px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
        <input placeholder="CVV" style="padding:13px 16px;border:2px solid #e5e7eb;border-radius:12px;font-size:14px;font-family:'DM Sans',sans-serif;outline:none;" onfocus="this.style.borderColor='#7c3aed'" onblur="this.style.borderColor='#e5e7eb'">
      </div>
      <button onclick="placeOrder()" style="width:100%;padding:16px;background:linear-gradient(135deg,#7c3aed,#a78bfa);color:white;border:none;border-radius:50px;font-size:15px;font-weight:600;cursor:pointer;font-family:'DM Sans',sans-serif;box-shadow:0 8px 20px rgba(124,58,237,0.3);">Place Order — $${total.toFixed(2)}</button>
    </div>`;
  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
}

function closeCheckoutModal() {
  const m = document.getElementById('checkout-modal');
  if (m) m.style.display = 'none';
  document.body.style.overflow = '';
}

function placeOrder() {
  closeCheckoutModal();
  clearCart();
  closeCart();
  showToast('Order placed! Thank you for shopping with Violet Beauty 🌸');
  setTimeout(() => showToast('You\'ll receive a confirmation email shortly 💜'), 2000);
}

// Checkout button
