// ===== SEARCH MODAL =====
function openSearch() {
  let modal = document.getElementById('search-modal');
  if (!modal) {
    modal = document.createElement('div');
    modal.id = 'search-modal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:9000;display:flex;align-items:flex-start;justify-content:center;padding:100px 20px;';
    modal.innerHTML = `
      <div style="position:absolute;inset:0;background:rgba(0,0,0,0.6);backdrop-filter:blur(10px);" onclick="closeSearch()"></div>
      <div style="background:white;border-radius:24px;padding:0;width:100%;max-width:600px;position:relative;z-index:1;box-shadow:0 30px 80px rgba(0,0,0,0.3);overflow:hidden;animation:modal-in 0.3s ease;">
        <div style="display:flex;align-items:center;padding:20px 24px;border-bottom:1px solid #f0f0f0;">
          <span style="font-size:20px;margin-right:12px;">🔍</span>
          <input id="search-input" placeholder="Search products, categories..." style="flex:1;border:none;outline:none;font-size:16px;font-family:'DM Sans',sans-serif;color:#18181b;" oninput="handleSearch(this.value)" autofocus>
          <button onclick="closeSearch()" style="background:none;border:none;font-size:18px;cursor:pointer;color:#9ca3af;margin-left:12px;">✕</button>
        </div>
        <div id="search-results" style="padding:16px;max-height:400px;overflow-y:auto;">
          <div style="text-align:center;padding:30px;color:#9ca3af;font-size:14px;">Start typing to search...</div>
        </div>
      </div>`;
    document.body.appendChild(modal);
  }
  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
  setTimeout(() => document.getElementById('search-input')?.focus(), 100);
}

function closeSearch() {
  const m = document.getElementById('search-modal');
  if (m) m.style.display = 'none';
  document.body.style.overflow = '';
}

