function handleSearch(query) {
  const results = document.getElementById('search-results');
  if (!query.trim()) { results.innerHTML = '<div style="text-align:center;padding:30px;color:#9ca3af;font-size:14px;">Start typing to search...</div>'; return; }
  const matches = SEARCH_PRODUCTS.filter(p => p.name.toLowerCase().includes(query.toLowerCase()) || p.category.toLowerCase().includes(query.toLowerCase()));
  if (matches.length === 0) { results.innerHTML = '<div style="text-align:center;padding:30px;color:#9ca3af;font-size:14px;">No products found</div>'; return; }
  results.innerHTML = matches.map(p => `
    <div style="display:flex;align-items:center;gap:14px;padding:12px 16px;border-radius:14px;cursor:pointer;transition:background 0.2s;" onmouseover="this.style.background='#f5f3ff'" onmouseout="this.style.background=''">
      <div style="width:44px;height:44px;background:linear-gradient(135deg,#f3e8ff,#fce7f3);border-radius:12px;overflow:hidden;flex-shrink:0;"><img src="data:image/png;base64," alt="" style="width:100%;height:100%;object-fit:cover;"></div>
      <div style="flex:1;">
        <div style="font-size:14px;font-weight:600;color:#18181b;">${p.name}</div>
        <div style="font-size:12px;color:#9ca3af;">${p.category}</div>
      </div>
      <div style="font-weight:700;color:#7c3aed;font-size:14px;">$${p.price}</div>
      <button onclick="addToCart('${p.name}', ${p.price}, '<i class="fa-solid fa-pump-soap"></i>');closeSearch();" style="padding:7px 14px;background:linear-gradient(135deg,#7c3aed,#a78bfa);color:white;border:none;border-radius:50px;font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap;">Add to Cart</button>
    </div>`).join('');
}

